// GHIW-60: Initialize Watcher State
// Prepares state machine for hourly builder lease & orphan inspection.
// READ_ONLY — observes, never mutates.

const SCHEMA_VERSION = '1.0';
const PROJECT_ID = 'ghiw-n8n-ops-control-plane';
const ALLOWED_CT_RANGE = { min: 8000, max: 8999 };
const PROVISIONER_CONFIG_PATH = '/etc/ghiw/provisioner/config.json';
const REGISTRY_PATH = '/var/lib/ghiw-provisioner/registry.sqlite3';
const LOCKCTL_PATH = '/usr/local/sbin/ghiw-lockctl';

function toBase64Url(s) {
  const b64 = Buffer.from ? Buffer.from(s).toString('base64') : btoa(unescape(encodeURIComponent(s)));
  return b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

const runId = 'w1-ghiw60-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);

const state = {
  schema_version: SCHEMA_VERSION,
  project_id: PROJECT_ID,
  run_id: runId,
  task_id: 'GHIW-60',
  source: { type: 'schedule', id: new Date().toISOString() },
  workflow: { logical_id: 'GHIW-60', id: $workflow.id, name: $workflow.name },
  execution: { id: $execution.id, started_at: new Date().toISOString() },
  state: 'INIT',
  ct_range: ALLOWED_CT_RANGE,
  registry_builders: [],
  live_cts: [],
  builder_health: {},
  lock_state: null,
  findings: [],
  // SSH commands prepared for execution
  command: '',
  command_registry: toBase64Url(JSON.stringify({schema_version:'1.0', operation:'list-builders'})),
  command_cts: toBase64Url(JSON.stringify({schema_version:'1.0', ct_min:8000, ct_max:8999})),
  command_locks: toBase64Url(JSON.stringify({schema_version:'1.0', operation:'inspect'})),
  timestamp: new Date().toISOString()
};

return [{ json: state }];

// GHIW-60: Query Registry
// Prepares SQL query to fetch all builders from registry.
// In production: executed via SSH to Proxmox host.
// For Wave 1: produces a simulated registry response for contract testing.

const state = $input.first().json;

// Simulated registry query (in production: SSH: sqlite3 registry.sqlite3)
const simulatedRegistry = [
  {
    builder_id: 'bld-8001',
    project_id: 'e3r6-canary-001',
    ctid: 8001,
    hostname: 'ghiw-bld-e3r6-canary-001-8001',
    template_id: 'ct109',
    current_state: 'BUILDER_READY',
    created_at: '2026-08-01T20:23:25Z',
    updated_at: '2026-08-01T20:23:32Z'
  },
  {
    builder_id: 'bld-8000',
    project_id: 'ghiw-phase2-canary',
    ctid: 8000,
    hostname: 'ghiw-bld-ghiw-phase2-canary-aeb7b6b',
    template_id: 'ct109',
    current_state: 'BUILDER_READY',
    created_at: '2026-07-30T00:00:00Z',
    updated_at: '2026-07-30T00:00:00Z'
  }
];

state.registry_builders = simulatedRegistry;
state.state = 'REGISTRY_QUERIED';

return [{ json: state }];

// GHIW-60: Cross-Reference Registry vs Live CT Reality
// Compares registry entries against known live CT state.
// Produces findings array with deterministic classification.

const state = $input.first().json;

// Simulated live CT state (in production: from 'pct list' via SSH)
const liveCTs = [
  { ctid: 8000, status: 'running', hostname: 'ghiw-bld-ghiw-phase2-canary-aeb7b6b' },
  { ctid: 8001, status: 'running', hostname: 'ghiw-bld-e3r6-canary-001-8001' }
];
state.live_cts = liveCTs;

const registryCTIds = new Set(state.registry_builders.map(b => b.ctid));
const liveCTIds = new Set(liveCTs.map(ct => ct.ctid));
const findings = [];

// Check: Registry entries without live CTs
for (const builder of state.registry_builders) {
  if (!liveCTIds.has(builder.ctid)) {
    findings.push({
      type: 'ORPHAN_REGISTRY_ENTRY',
      builder_id: builder.builder_id,
      ctid: builder.ctid,
      detail: 'Registry entry exists but CT not found running'
    });
  }
}

// Check: Live CTs without registry entries
for (const ct of liveCTs) {
  if (!registryCTIds.has(ct.ctid)) {
    findings.push({
      type: 'ORPHAN_BUILDER',
      ctid: ct.ctid,
      hostname: ct.hostname,
      detail: 'CT is running but not registered'
    });
  }
}

// Check: Builder state consistency
for (const builder of state.registry_builders) {
  const liveCT = liveCTs.find(ct => ct.ctid === builder.ctid);
  if (liveCT) {
    if (liveCT.status !== 'running' && builder.current_state === 'BUILDER_READY') {
      findings.push({
        type: 'STATE_DRIFT',
        builder_id: builder.builder_id,
        ctid: builder.ctid,
        registry_state: builder.current_state,
        live_status: liveCT.status
      });
    }
  }
}

// Check: CTs outside allowed range
for (const ct of liveCTs) {
  if (ct.ctid < state.ct_range.min || ct.ctid > state.ct_range.max) {
    findings.push({
      type: 'CTID_OUT_OF_RANGE',
      ctid: ct.ctid,
      detail: `CTID ${ct.ctid} outside allowed range ${state.ct_range.min}-${state.ct_range.max}`
    });
  }
}

state.findings = findings;
state.state = 'CROSS_REFERENCED';

return [{ json: state }];

// GHIW-60: Classify & Produce Verdict
// Deterministic classification based on findings array.
// Output: HEALTHY or specific drift/alert classification.
// NEVER mutates infrastructure.

const state = $input.first().json;

let decision = 'HEALTHY';
let reason_codes = ['ALL_BUILDERS_HEALTHY'];

if (state.findings.length > 0) {
  // Prioritize by severity
  const types = state.findings.map(f => f.type);

  if (types.includes('ORPHAN_BUILDER') && types.includes('ORPHAN_REGISTRY_ENTRY')) {
    decision = 'MANUAL_REVIEW_REQUIRED';
    reason_codes = types.map(t => t === 'ORPHAN_BUILDER' ? 'BUILDER_WITHOUT_LEASE' : 'REGISTRY_ENTRY_ORPHANED');
  } else if (types.includes('STATE_DRIFT')) {
    decision = 'STATE_DRIFT';
    reason_codes = ['STATE_MISMATCH'];
  } else if (types.includes('ORPHAN_BUILDER')) {
    decision = 'ORPHAN_BUILDER';
    reason_codes = ['CT_NOT_IN_REGISTRY'];
  } else if (types.includes('ORPHAN_REGISTRY_ENTRY')) {
    decision = 'ORPHAN_REGISTRY_ENTRY';
    reason_codes = ['REGISTRY_ENTRY_ORPHANED'];
  } else if (types.includes('CTID_OUT_OF_RANGE')) {
    decision = 'STATE_DRIFT';
    reason_codes = ['CTID_OUT_OF_RANGE'];
  } else {
    decision = 'MANUAL_REVIEW_REQUIRED';
    reason_codes = ['RECONCILIATION_NEEDED'];
  }
}

// Build output envelope
const output = {
  schema_version: state.schema_version,
  project_id: state.project_id,
  run_id: state.run_id,
  task_id: state.task_id,
  source: state.source,
  workflow: state.workflow,
  execution: { ...state.execution, completed_at: new Date().toISOString() },
  decision: decision,
  reason_codes: reason_codes,
  evidence_refs: [],
  classification: decision === 'HEALTHY' ? 'GREEN' : 'AMBER',
  timestamp: new Date().toISOString(),
  watcher_details: {
    registry_builders_count: state.registry_builders.length,
    live_cts_count: state.live_cts.length,
    findings_count: state.findings.length,
    findings: state.findings
  }
};

return [{ json: output }];

